/* Eltiz Builder Motion Effects v1.0.0 | GPL-2.0-or-later */
(function(){
'use strict';

/* ── Entrance Animations ─────────────────────────────────────── */
if('IntersectionObserver' in window){
  var animObserver = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(!entry.isIntersecting) return;
      var el       = entry.target;
      var anim     = el.dataset.eltizAnimation;
      var duration = el.dataset.eltizAnimationDuration || '1000';
      var delay    = el.dataset.eltizAnimationDelay    || '0';
      el.style.animationDuration = duration + 'ms';
      el.style.animationDelay    = delay + 'ms';
      el.classList.add('eltiz-animated', 'eltiz-' + anim);
      el.style.visibility = 'visible';
      animObserver.unobserve(el);
    });
  }, { threshold: 0.1 });

  document.querySelectorAll('[data-eltiz-animation]').forEach(function(el){
    el.style.visibility = 'hidden';
    animObserver.observe(el);
  });
}

/* ── Scroll Parallax ────────────────────────────────────────── */
var parallaxEls = Array.from(document.querySelectorAll('[data-eltiz-parallax]'));
if(parallaxEls.length){
  function updateParallax(){
    var scrollY = window.scrollY;
    parallaxEls.forEach(function(el){
      var speed  = parseFloat(el.dataset.eltizParallaxSpeed || 0.5);
      var rect   = el.getBoundingClientRect();
      var center = rect.top + rect.height / 2 + scrollY - window.innerHeight / 2;
      var offset = -(center * speed);
      el.style.transform = 'translateY(' + offset + 'px)';
    });
  }
  window.addEventListener('scroll', updateParallax, { passive: true });
  updateParallax();
}

/* ── Sticky Elements ────────────────────────────────────────── */
document.querySelectorAll('[data-eltiz-sticky]').forEach(function(el){
  var offset   = parseInt(el.dataset.eltizStickyOffset || 0, 10);
  var origTop  = el.getBoundingClientRect().top + window.scrollY;
  var placeholder = null;

  window.addEventListener('scroll', function(){
    var scrollY = window.scrollY;
    if(scrollY + offset >= origTop){
      if(!placeholder){
        placeholder = document.createElement('div');
        placeholder.style.height = el.offsetHeight + 'px';
        el.parentNode.insertBefore(placeholder, el);
      }
      el.style.position = 'fixed';
      el.style.top      = offset + 'px';
      el.style.zIndex   = '999';
      el.classList.add('eltiz-sticky--active');
    } else {
      if(placeholder){ placeholder.parentNode.removeChild(placeholder); placeholder = null; }
      el.style.position = '';
      el.style.top      = '';
      el.style.zIndex   = '';
      el.classList.remove('eltiz-sticky--active');
    }
  }, { passive: true });
});

})();
